/* New York Giants DNA — Big blue, franchise red. */
.theme-new-york-giants {
  --bg: oklch(0.286 0.121 264.8);
  --surface: oklch(0.323 0.143 264.7);
  --surface-2: oklch(0.363 0.164 264.6);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.652 0.155 267.9);
  --accent: oklch(0.472 0.174 19.7);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.698 0.094 258.8);
  --line: oklch(1 0 0 / 14%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.788 0.151 74.9);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.375rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Graduate", serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0.04em;
  --label-transform: uppercase;
  --label-tracking: 0.12em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-new-york-giants h1,
.theme-new-york-giants h2,
.theme-new-york-giants h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-new-york-giants { --font-ui: var(--font-display); }
.theme-new-york-giants h1, .theme-new-york-giants h2 { text-transform: uppercase; }
.theme-new-york-giants h1::after { content: ""; display: block; height: 5px; width: 6rem; margin-top: 0.6rem; background: linear-gradient(90deg, var(--accent) 0 50%, var(--accent-2) 50% 100%); }
.theme-new-york-giants button { text-transform: uppercase; letter-spacing: 0.1em; font-weight: 600; }
.theme-new-york-giants th { color: var(--accent); text-transform: uppercase; letter-spacing: 0.12em; font-size: 11px; border-bottom: 2px solid var(--accent); }
.theme-new-york-giants tbody tr:hover { background: color-mix(in oklab, var(--accent) 8%, transparent); }
.theme-new-york-giants h2 { border-bottom: 3px solid var(--accent); display: inline-block; padding-bottom: 0.15em; }
.theme-new-york-giants ::selection { background: var(--accent); color: var(--accent-fg); }


/* alt mode: road whites */
.theme-new-york-giants.alt-mode {
  --bg: oklch(0.98 0.001 260); --surface: oklch(1 0 0); --surface-2: oklch(0.94 0.002 260);
  --fg: oklch(0.2 0.005 260); --fg-muted: oklch(0.45 0.005 260); --line: oklch(0.89 0.003 260);
  --accent: oklch(0.472 0.174 19.7); --accent-fg: oklch(1.000 0 0);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%); --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%); --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: none;
}
.theme-new-york-giants.alt-mode h1 { color: oklch(0.472 0.174 19.7); }
.theme-new-york-giants.alt-mode h2, .theme-new-york-giants.alt-mode h3 { color: oklch(0.472 0.174 19.7); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);
}
